-- TASK-220 candidate revisions for 22 already PUBLISHED, high-risk M12 questions.
-- This creates 22 independent REVIEW items; it never edits published source, answers or attempt history.
BEGIN;
DO $stylefix$
DECLARE x jsonb; subj uuid; lesson uuid; cons uuid; qid uuid; oid uuid; ans uuid; i int; n int;
BEGIN
 SELECT id INTO STRICT subj FROM public.subjects WHERE code='informatika';
 FOR x IN SELECT value FROM jsonb_array_elements($items$[{"id":"M12-REV26-01-001","original_id":"TAR-01-001","ch":1,"stem":"Kompyuter tarmog‘i tashkil etilishining eng asosiy maqsadini aniqlang.","options":["Qurilmalar o‘rtasida resurs va axborot almashishni ta’minlash","Kompyuterni faqat internetga ulash","Bir kompyuter xotirasini kengaytirish","Har bir qurilmada bir xil operatsion tizim bo‘lishini ta’minlash"],"answer":"A","exp":"Tarmoq qurilmalar va xizmatlarning o'zaro axborot almashuviga xizmat qiladi.","source":"M11, 129--139-betlar; C8, PDF 91--96","code":"S6.NET.01"},{"id":"M12-REV26-01-011","original_id":"TAR-01-011","ch":1,"stem":"LAN atamasining to‘liq yozilishini aniqlang.","options":["Wide Area Network","Metropolitan Area Network","Local Area Network","Personal Area Network"],"answer":"C","exp":"LAN mahalliy hududdagi qurilmalarni birlashtiradi.","source":"M11, 129--139-betlar; C8, PDF 91--96","code":"S6.NET.01"},{"id":"M12-REV26-01-012","original_id":"TAR-01-012","ch":1,"stem":"Bitta xonada joylashgan 20 ta kompyuter bir switchga Ethernet orqali ulangan. Hududiy ko‘lam bo‘yicha qaysi turdagi tarmoq?","options":["WAN","MAN","PAN","LAN"],"answer":"D","exp":"LAN mahalliy hududdagi qurilmalarni birlashtiradi.","source":"M11, 129--139-betlar; C8, PDF 91--96","code":"S6.NET.01"},{"id":"M12-REV26-01-014","original_id":"TAR-01-014","ch":1,"stem":"Bitta ofisdagi noutbuklar yagona Wi-Fi kirish nuqtasiga ulangan. Ularga mos tarmoq turi qaysi?","options":["WAN","WLAN","MAN","PAN"],"answer":"B","exp":"WLAN — radioaloqa asosidagi mahalliy LAN.","source":"M11, 129--139-betlar; C8, PDF 91--96","code":"S6.NET.01"},{"id":"M12-REV26-01-016","original_id":"TAR-01-016","ch":1,"stem":"Bir shaharning bir necha tumanidagi idoralar bitta aloqa infratuzilmasida bog‘langan. Tarmoq hududiy tasnifini aniqlang.","options":["PAN","LAN","WAN","MAN"],"answer":"D","exp":"MAN odatda shahar miqyosida birlashgan tarmoqlarga nisbatan ishlatiladi.","source":"M11, 129--139-betlar; C8, PDF 91--96","code":"S6.NET.01"},{"id":"M12-REV26-01-018","original_id":"TAR-01-018","ch":1,"stem":"Turli viloyatlarda joylashgan ikki korxona filialining lokal tarmoqlari o‘zaro uzatish kanali bilan bog‘langan. Qamrov jihatidan qanday tarmoq?","options":["PAN","WAN","LAN","MAN"],"answer":"B","exp":"WAN uzoq joylashgan hududlarni birlashtiradi.","source":"M11, 129--139-betlar; C8, PDF 91--96","code":"S6.NET.01"},{"id":"M12-REV26-01-020","original_id":"TAR-01-020","ch":1,"stem":"Uy routeri orqali televizor, telefon va noutbuk bitta mahalliy tarmoqqa ulangan. Hududiy tasnif uchun eng mos nom?","options":["WAN","MAN","PAN","LAN"],"answer":"D","exp":"HAN uy hududidagi o'zaro ulangan qurilmalarni ifodalaydi.","source":"M11, 129--139-betlar; C8, PDF 91--96","code":"S6.NET.01"},{"id":"M12-REV26-01-022","original_id":"TAR-01-022","ch":1,"stem":"Maktabda provayder interneti uzildi, biroq mahalliy IP bilan ishlaydigan printer mavjud. Qaysi hukm texnik jihatdan to‘g‘ri?","options":["LANdagi har bir xizmat DNSning tashqi serveriga bog‘liq","Mahalliy printer internet uzilganda ham ishlashi mumkin","Bitta LANdagi barcha aloqa faqat provayder orqali o‘tadi","Switch va printer o‘rtasidagi aloqa uchun tashqi router doimo shart"],"answer":"B","exp":"Lokal LAN aloqa provayder internetiga bog‘liq bo‘lmasligi mumkin.","source":"M11, 129--139-betlar; C8, PDF 91--96","code":"S6.NET.01"},{"id":"M12-REV26-02-005","original_id":"TAR-02-005","ch":2,"stem":"A va B lokal IP subnetlari orasida paket o‘tishi uchun qaysi qurilmaning asosiy funksiyasi talab etiladi?","options":["MAC freymlarni bitta segment ichida kommutatsiya qilish","IP tarmoqlar orasida paketlarni marshrutlash","Simsiz SSIDni radio orqali tarqatish","IPga mos domen yozuvini DNSda saqlash"],"answer":"B","exp":"Router IP sarlavha va marshrutga qarab paket uzatadi.","source":"M11, 146--166-betlar; C8, PDF 98--106","code":"S6.NET.01"},{"id":"M12-REV26-04-006","original_id":"TAR-04-006","ch":4,"stem":"IP manzil bilan serverga aloqa bor, lekin domen orqali kirish ishlamaydi. Qaysi komponentni tekshirish eng asosli?","options":["DNS nomini IPga yechish xizmati","MAC jadvalining yoshini belgilash","TCP segment oynasi hajmi","DHCP serverdagi mavjud ijara muddati"],"answer":"A","exp":"IP bo'yicha aloqaning mavjudligi DNS muammosini ko'rsatishi mumkin.","source":"M11, 186--192-betlar","code":"S6.NET.02"},{"id":"M12-REV26-08-014","original_id":"TAR-08-014","ch":8,"stem":"Brauzer HTTP protokoli bilan shifrlanmagan standart xizmatga ulanmoqda. Serverning odatiy TCP porti qaysi?","options":["80","22","443","53"],"answer":"A","exp":"HTTP ko'p holatda TCP 80 portidan foydalanadi.","source":"M11, 186--195-betlar; M6, 77--85-betlar","code":"S6.NET.05"},{"id":"M12-REV26-08-016","original_id":"TAR-08-016","ch":8,"stem":"Brauzer HTTPS xizmatiga maxsus port ko‘rsatilmasdan ulanmoqda. Odatiy TCP port qaysi?","options":["80","25","443","53"],"answer":"C","exp":"HTTPSning odatdagi TCP porti 443.","source":"M11, 186--195-betlar; M6, 77--85-betlar","code":"S6.NET.05"},{"id":"M12-REV26-05-014","original_id":"TAR-05-014","ch":5,"stem":"255.255.255.224 IPv4 niqobidagi ketma-ket 1 bitlar soni nechta?","options":["28","27","26","29"],"answer":"B","exp":"Maskaning ikkilik ko‘rinishida 27 ta 1 bit bor.","source":"M11, 172--179-betlar; texnik aniqlashtirish: RFC 4632","code":"S6.NET.03"},{"id":"M12-REV26-05-020","original_id":"TAR-05-020","ch":5,"stem":"Quyidagi IPv4 manzil toifalaridan 127.0.0.1 ga mosini tanlang.","options":["Multicast","Link-local","RFC1918 private","Loopback"],"answer":"D","exp":"127/8 loopback uchun ajratilgan, RFC 1918 xususiy diapazon emas.","source":"M11, 172--179-betlar; texnik aniqlashtirish: RFC 4632","code":"S6.NET.03"},{"id":"M12-REV26-05-022","original_id":"TAR-05-022","ch":5,"stem":"224.0.0.9 manzili IPv4 ning qaysi guruhiga kiradi?","options":["RFC1918 private","Multicast","Loopback","Link-local"],"answer":"B","exp":"224/4 multicast guruhlariga ajratilgan.","source":"M11, 172--179-betlar; texnik aniqlashtirish: RFC 4632","code":"S6.NET.03"},{"id":"M12-REV26-07-007","original_id":"TAR-07-007","ch":7,"stem":"30 ta oddiy foydalaniladigan IPv4 xost kerak. Network va broadcast ajratilishini hisobga olib eng katta CIDR prefiksni tanlang.","options":["/27","/28","/26","/29"],"answer":"A","exp":"2^5-2=30 ta usable manzil /27 da mavjud; undan kichik blok yetmaydi.","source":"M11, 180--185-betlar; texnik aniqlashtirish: RFC 4291","code":"S6.NET.03"},{"id":"M12-REV26-07-011","original_id":"TAR-07-011","ch":7,"stem":"62 ta oddiy foydalaniladigan IPv4 host uchun eng kichik subnetni ta’minlaydigan prefiksni tanlang.","options":["/26","/27","/25","/28"],"answer":"A","exp":"2^6-2=62 ta usable manzil /26 da mavjud; undan kichik blok yetmaydi.","source":"M11, 180--185-betlar; texnik aniqlashtirish: RFC 4291","code":"S6.NET.03"},{"id":"M12-REV26-07-013","original_id":"TAR-07-013","ch":7,"stem":"192.168.16.0/24 manzil blokini teng 4 qismga ajratish uchun yangi subnet prefiksi nechchi?","options":["/25","/27","/26","/28"],"answer":"C","exp":"4=2^2; tarmoqdan 2 qo'shimcha bit olinadi: /24+2=/26.","source":"M11, 180--185-betlar; texnik aniqlashtirish: RFC 4291","code":"S6.NET.03"},{"id":"M12-REV26-07-014","original_id":"TAR-07-014","ch":7,"stem":"192.168.50.0/24 ni 4 ta teng subnetga bo‘lishda qanday yangi prefiks hosil bo‘ladi?","options":["/25","/27","/28","/26"],"answer":"D","exp":"4=2^2 yangi tarmoq biti olinadi: /24+2=/26.","source":"M11, 180--185-betlar; texnik aniqlashtirish: RFC 4291","code":"S6.NET.03"},{"id":"M12-REV26-07-016","original_id":"TAR-07-016","ch":7,"stem":"10.4.0.0/24 tarmog‘idan 16 ta teng blok olish uchun nechta qo‘shimcha bit subnetga ajratiladi va yakuniy prefiks qaysi?","options":["3 bit, /27","4 bit, /28","5 bit, /29","2 bit, /26"],"answer":"B","exp":"16=2^4 yangi tarmoq biti olinadi: /24+4=/28.","source":"M11, 180--185-betlar; texnik aniqlashtirish: RFC 4291","code":"S6.NET.03"},{"id":"M12-REV26-07-018","original_id":"TAR-07-018","ch":7,"stem":"10.25.0.0/23 blokini 4 ta teng subnetga ajratsak, yangi prefiks nima bo‘ladi?","options":["/24","/26","/27","/25"],"answer":"D","exp":"4=2^2 yangi tarmoq biti olinadi: /23+2=/25.","source":"M11, 180--185-betlar; texnik aniqlashtirish: RFC 4291","code":"S6.NET.03"},{"id":"M12-REV26-07-021","original_id":"TAR-07-021","ch":7,"stem":"10.100.64.0/20 bazaviy blokini 16 ta bir xil hajmdagi subnetga bo‘lish natijasidagi prefiksni tanlang.","options":["/22","/23","/24","/25"],"answer":"C","exp":"16=2^4 yangi tarmoq biti olinadi: /20+4=/24.","source":"M11, 180--185-betlar; texnik aniqlashtirish: RFC 4291","code":"S6.NET.03"}]$items$::jsonb) LOOP
   lesson:=md5('task220-m12-v2-lesson-'||(x->>'ch'))::uuid;
   SELECT id INTO STRICT cons FROM public.constructs WHERE code=x->>'code' AND group_code='S6.NET';
   IF NOT EXISTS (SELECT 1 FROM public.lessons l JOIN public.modules m ON m.id=l.module_id
     JOIN public.lesson_constructs lc ON lc.lesson_id=l.id AND lc.construct_id=cons
     WHERE l.id=lesson AND l.slug like 'tarmoq-v2-bob-%' AND m.code='M12'
     AND l.status IN ('draft','published')) THEN
        RAISE EXCEPTION 'M12 V2 lesson mapping missing, %',x->>'id';
   END IF;
   qid:=md5('task220-stylefix-review-'||(x->>'id'))::uuid;
   INSERT INTO public.questions
    (id,subject_id,construct_id,group_code,format,cognitive,difficulty,stem_md,assets,status,source_reference,source_lesson_id)
   VALUES(qid,subj,cons,'S6.NET','Y1'::public.question_format,'qollash'::public.cognitive_level,
     3,x->>'stem','[]'::jsonb,'review'::public.content_status,'m12-stylefix-20261020:'||(x->>'id'),lesson)
   ON CONFLICT(id) DO NOTHING;
   IF NOT EXISTS(SELECT 1 FROM public.questions WHERE id=qid AND status='review'::public.content_status
    AND source_reference='m12-stylefix-20261020:'||(x->>'id') AND stem_md=x->>'stem')
   THEN RAISE EXCEPTION 'Item version collision %',x->>'id'; END IF;
   ans:=NULL;
   FOR i IN 0..3 LOOP
     oid:=md5('task220-stylefix-option-'||(x->>'id')||'-'||i)::uuid;
     INSERT INTO public.question_options(id,question_id,side,order_idx,content_md)
       VALUES(oid,qid,'a',i+1,x->'options'->>i) ON CONFLICT(id) DO NOTHING;
     IF i=ascii(x->>'answer')-65 THEN ans:=oid; END IF;
   END LOOP;
   IF ans IS NULL THEN RAISE EXCEPTION 'Correct answer missing %',x->>'id'; END IF;
   INSERT INTO public.question_keys(question_id,payload,explanation_md)
    VALUES(qid,jsonb_build_object('correct_option_id',ans),
      (x->>'exp')||E'\n\nRevised source: '||(x->>'source')||
      E'\nProposed replacement for published item: '||(x->>'original_id')||
      E'\nReview only; original item unchanged.')
    ON CONFLICT(question_id) DO NOTHING;
 END LOOP;
 SELECT count(*) INTO n FROM public.questions WHERE source_reference like 'm12-stylefix-20261020:%';
 IF n<>22 THEN RAISE EXCEPTION 'Expected 22 revision proposals, got %',n; END IF;
END $stylefix$;
COMMIT;
